import test from 'node:test';import assert from 'node:assert/strict';import { createState, step } from '../../src/physics.js';test('terminal speed clamps downward velocity', async t => {
  const level = { spawn: [0, 10, 0], killY: -12, platforms: [], coins: [], goal: {id:'g',min:[0,0,0],max:[0,0,0]} };
  let state = createState(level);
  state.grounded = false;
  state.vel = [0, -25, 0];
  const idle = {x:0, z:0, jump:false};
  state = step(state, idle, level, 0);
  assert.equal(state.vel[1], -18);
  state = step(state, idle, level, 1);
  assert.equal(state.vel[1], -18);
});

import test from 'node:test';import assert from 'node:assert/strict';import { createState, step } from '../../src/physics.js';test('horizontal speed clamps to max run speed', async t => {
  const level = { spawn: [0, 0, 0], killY: -12, platforms: [{id:'p',min:[0,-1,0],max:[1,0,1]}], coins: [], goal: {id:'g',min:[0,0,0],max:[0,0,0]} };
  let state = createState(level);
  state.grounded = true;
  state.vel = [12, 0, 0];
  const input = {x:1, z:0, jump:false};
  state = step(state, input, level, 0);
  const speed = Math.sqrt(state.vel[0]*state.vel[0] + state.vel[2]*state.vel[2]);
  assert.equal(speed, 10);
});

