import test from 'node:test';import assert from 'node:assert/strict';import { createState, step } from '../../src/physics.js';test('coin collection is idempotent and tracked by index', async t => {
  const level = {
    spawn: [0, 2, 0],
    killY: -12,
    platforms: [{id:'p',min:[0,0,0],max:[1,0.2,1]}],
    coins: [[0.5, 1.8, 0.5]],
    goal: {id:'g',min:[0,0,0],max:[0,0,0]}
  };
  let state = createState(level);
  state.pos = [0.5, 1.8, 0.5];
  state.vel = [0, 0, 0];
  state.grounded = true;
  const input = {x:0, z:0, jump:false};
  state = step(state, input, level, 0);
  assert.deepEqual(state.coins, [0]);
  state = step(state, input, level, 1);
  assert.deepEqual(state.coins, [0]);
});

import test from 'node:test';import assert from 'node:assert/strict';import { createState, step } from '../../src/physics.js';test('respawn increments deaths and resets state but keeps coins', async t => {
  const level = {
    spawn: [0, 1, 0],
    killY: 0,
    platforms: [],
    coins: [[0, 2, 0]],
    goal: {id:'g',min:[0,0,0],max:[0,0,0]}
  };
  let state = createState(level);
  state.coins = [0];
  state.deaths = 2;
  state.pos = [0, -1, 0];
  state.vel = [0, -1, 0];
  const input = {x:0, z:0, jump:false};
  state = step(state, input, level, 0);
  assert.equal(state.deaths, 3);
  assert.deepEqual(state.pos, [0, 1, 0]);
  assert.deepEqual(state.vel, [0, 0, 0]);
  assert.equal(state.grounded, true);
  assert.deepEqual(state.coins, [0]);
});
